'use strict';
(function(root){
 const permutations=a=>a.length?a.flatMap((v,i)=>permutations(a.filter((_,j)=>i!==j)).map(p=>[v,...p])):[[]];
 // Require strict separation; no assumptions about ties or enemy speed distributions.
 function speedTargets(order,actors,ratio,enemyMax){const needed={};let next=enemyMax;for(let i=order.length-1;i>=0;i--){const actor=actors[order[i]];let threshold=Math.floor(next/actor.speedMultiplier)+1;needed[order[i]]=Math.max(actor.speed,threshold);next=needed[order[i]]*actor.speedMultiplier*ratio;}return needed;}
 function simulate(actors,order,openers,turns,optimistic,hp=Infinity){let damage=0,steps=[],buffs=[],mp=actors.map(a=>a.mp),spent=actors.map(()=>0);for(let turn=1;turn<=turns;turn++)for(const index of order){const a=actors[index],skill=turn===1&&openers[index]?a.support:a.attack;if(mp[index]<skill.mp)return null;mp[index]-=skill.mp;spent[index]+=skill.mp;let dealt=0;if(skill.kind==='damage'){let factor=1;const grouped=Object.create(null);for(const effect of buffs){if(effect.expires<turn||(!optimistic&&effect.chance<1)||effect.type!=='全種'&&effect.type!==a.type||effect.target!=='全員'&&effect.owner!==index)continue;grouped[effect.group]=Math.max(grouped[effect.group]||1,effect.multiplier);}for(const v of Object.values(grouped))factor*=v;dealt=Math.floor((optimistic?skill.max:skill.min)*factor);if(!optimistic&&skill.hit<1)dealt=0;damage+=dealt;}else buffs.push({...skill,owner:index,expires:turn+skill.duration-1});steps.push({turn,index,skill:skill.name,damage:dealt,total:damage,mp:skill.mp});if(damage>=hp)return {damage,steps,spent};}return {damage,steps,spent};}
 function search(actors,options){if(actors.length!==4)throw Error('4人の登録が必要です。');if(!Number.isFinite(options.hp)||options.hp<=0)throw Error('敵HPを入力してください。');if(!(options.ratio>=1&&options.ratio<=2))throw Error('乱数上限倍率を確認してください。');let candidates=[];for(const order of permutations([0,1,2,3]))for(let mask=0;mask<16;mask++){const openers=actors.map((a,i)=>Boolean((mask>>i)&1));if(openers.some((on,i)=>on&&!actors[i].support))continue;const needed=speedTargets(order,actors,options.ratio,options.enemyMax??0);const deficit=order.reduce((sum,i)=>sum+needed[i]-actors[i].speed,0);const low=simulate(actors,order,openers,options.turns,false,options.hp),high=simulate(actors,order,openers,options.turns,true,options.hp);if(!low||!high)continue;const kill=low.steps.find(s=>s.total>=options.hp),possible=high.steps.find(s=>s.total>=options.hp);candidates.push({order,openers,needed,deficit,low,high,kill,possible});}candidates.sort((a,b)=>{const rank=c=>c.kill?(c.deficit===0?0:1):c.possible?2:3;return rank(a)-rank(b)||(a.kill?.turn??99)-(b.kill?.turn??99)||a.deficit-b.deficit||(a.kill?a.low.steps.indexOf(a.kill):99)-(b.kill?b.low.steps.indexOf(b.kill):99)||b.low.damage-a.low.damage;});return candidates.slice(0,3);}
 root.BattleEngine={search,simulate,speedTargets,permutations};if(typeof module!=='undefined')module.exports=root.BattleEngine;
})(typeof window==='undefined'?globalThis:window);
